"C:\\Users\\Admin\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command 'Add-Type -AssemblyName System.IO.Compression.FileSystem
$docPath = Join-Path (Get-Location) '"'format-source.docx'
"'$archive = [System.IO.Compression.ZipFile]::OpenRead($docPath)
try {
  $entry = $archive.GetEntry('"'word/document.xml')
  "'$reader = [System.IO.StreamReader]::new($entry.Open(), [System.Text.Encoding]::UTF8)
  try { $xmlText = $reader.ReadToEnd() } finally { $reader.Dispose() }
  [xml]$xml = $xmlText
  $ns = [System.Xml.XmlNamespaceManager]::new($xml.NameTable)
  $ns.AddNamespace('"'w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
  "'$paragraphs = $xml.SelectNodes('"'//w:p', "'$ns)
  for ($i = 0; $i -lt $paragraphs.Count; $i++) {
    $parts = $paragraphs[$i].SelectNodes('"'.//w:t', "'$ns)
    $textValue = ($parts | ForEach-Object { $_.'"'#text' }) -join ''
    if ("'$textValue) { '"'{0}: {1}' -f ("'$i + 1), $textValue }
  }
} finally { $archive.Dispose() }'

